(ife_summary__target, :gain) => IMASdd.Info(String[], "-", "FLT_0D", "Target gain G = E_fusion / E_laser", true, String[]),
(ife_summary__target, :gain_σ) => IMASdd.Info(String[], "-", "FLT_0D", "error of ife_summary.target.gain", true, String[]),
(ife_summary__target, :ifar) => IMASdd.Info(String[], "-", "FLT_0D", "In-flight aspect ratio of the imploding shell R/dR", true, String[]),
(ife_summary__target, :ifar_σ) => IMASdd.Info(String[], "-", "FLT_0D", "error of ife_summary.target.ifar", true, String[]),
(ife_summary__target, :implosion_velocity) => IMASdd.Info(String[], "m/s", "FLT_0D", "Peak implosion velocity of the shell", true, String[]),
